svg.script:
//

(async () => {
  try {
    const bin = atob(document.getElementById("page").textContent.trim());
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
    let text = await new Response(stream).text();
    text = text.replace("<head>", "<head><script>window.__BASE=" + JSON.stringify(location.href) + "<" + "/script>");
    const url = URL.createObjectURL(new Blob([text], { type: "text/html" }));
    location.replace(url);
  } catch (err) {
    document.getElementById("msg").textContent = "Vodious could not start: " + err + ". Open this file directly in an up-to-date Chrome, Edge, Firefox or Safari.";
  }
})();

